/bin/zsh -c "python3 - <<'PY'
import re
s=open('assembly.md').read()
s=re.sub(r'\\\\\\[.*?\\\\\\]','',s,flags=re.S)
stack=[]
for i,c in enumerate(s):
 if c=='(': stack.append(i)
 elif c==')' and stack:
  j=stack.pop()
  if not stack: print(repr(s[max(0,j-10):j]),repr(s[j:i+1]))
PY"

